// Pick the next topic for MoneyPrinterV2. The CLI turns a subject + optional
// script into a narrated faceless video (Pexels b-roll, TTS voice, subtitles).
// Configure a rotating list here or via the PICC_MP2_TOPICS env var (comma separated).
const list = ($env.PICC_MP2_TOPICS || '')
  .split(',')
  .map((t) => t.trim())
  .filter(Boolean);
const topics = list.length ? list : [
  'Top 5 passive income apps that still pay in 2026',
  'How much a $10K dividend portfolio pays every month',
  'DePIN: getting paid for your idle bandwidth in 2026'
];
const index = Math.floor(Date.now() / (1000 * 60 * 60 * 12)) % topics.length;
return [{
  json: {
    topic: topics[index],
    language: $json.language ?? 'zh-CN',
    voice: $json.voice ?? '',
    subtitleProvider: $json.subtitleProvider ?? 'edge',
    mp2Dir: $env.PICC_MP2_DIR || '$HOME/dev/moneyprinterv2'
  }
}];

// MoneyPrinterV2 prints the generated video path (e.g. `Save video to:`).
// Fall back to the newest .mp4 under its output folder.
const stdout = (Array.isArray($json) ? $json[0]?.stdout : $json.stdout) || '';
const lines = String(stdout).split(/\r?\n/).map((l) => l.trim()).filter(Boolean);
const videoLine = lines.find((l) => /mp4/i.test(l) && /\w/.test(l));
const outDir = $json.mp2Dir + '/storage/tasks';
return [{
  json: {
    topic: $json.topic,
    videoPath: videoLine || outDir,
    title: $json.topic,
    description: 'Faceless passive income explainer generated by the PICC MoneyMaker pipeline (MoneyPrinterV2).',
    tags: ['passive income', 'make money online', 'faceless youtube'],
    language: $json.language,
    mp2Dir: $json.mp2Dir
  }
}];

// Last node: keep a run log so the pipeline shows what was produced even
// when YouTube upload is disabled (review the video manually first).
return [{
  json: {
    ok: true,
    timestamp: new Date().toISOString(),
    topic: $json.topic,
    videoPath: $json.videoPath,
    uploaded: !$execution ? false : ($json.uploaded ?? false)
  }
}];
